code.source:
#include <iostream>
using namespace std;

template <typename T>
T biggest(T a, T b) {
    return a > b ? a : b;
}

int main() {
    cout << biggest(3, 8) << endl;
    cout << biggest(2.5, 1.5) << endl;
    return 0;
}

#include <iostream>
using namespace std;

template <typename T>
T biggest(T a, T b) {
    return a > b ? a : b;
}

int main() {
    cout << biggest<double>(3, 4.5) << endl;
    cout << biggest<string>("pear", "apple") << endl;
    return 0;
}

